BEGIN;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF ((SELECT count(*)=0 FROM platform.contacts)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|missing_context_hides_contacts'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-test@example.invalid','synthetic','Test Contact'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|missing_context_cannot_create'; END $test$;
SET LOCAL app.business_id='40000000-0000-4000-8000-000000001101';
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-test@example.invalid','synthetic','Test Contact'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|actor_required'; END $test$;
SET LOCAL app.actor_ref='phase5_test_actor';
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF ((SELECT count(*)=3 AND bool_and(business_id='40000000-0000-4000-8000-000000001101') FROM platform.contacts)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|three_contacts_only_in_authorized_business'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF (NOT EXISTS(SELECT 1 FROM platform.contacts WHERE id='50000000-0000-4000-8000-000000010101')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|other_business_profile_hidden'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000001202','phase5-test@example.invalid','synthetic','Test Contact'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|other_business_instance_rejected'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000001102','synthetic-person-3@example.invalid','synthetic','Test Contact'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|blocked_contact_rejected'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM platform.ensure_contact('40000000-0000-4000-8000-000000001102','bad@example.invalid','invalid','Test'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '22023' THEN NULL; END; RAISE NOTICE 'P5PASS|invalid_identity_kind_rejected'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN SELECT count(*) INTO n FROM platform.audit_events; c:=platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-new@example.invalid','synthetic','Original Synthetic Name'); IF (c=platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-new@example.invalid','synthetic','Untrusted Changed Name')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT display_name='Original Synthetic Name' FROM platform.contacts WHERE id=c)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT count(*)=n+1 FROM platform.audit_events)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT count(*)=1 FROM platform.channel_identities WHERE jid='phase5-new@example.invalid')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|contact_create_replay_audit_and_profile_preservation'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF (platform.ensure_contact('40000000-0000-4000-8000-000000001102','synthetic-person-1@example.invalid','synthetic','Test Contact')='50000000-0000-4000-8000-000000010001'::uuid) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|shared_identity_does_not_merge_businesses'; END $test$;
SET LOCAL app.business_id='40000000-0000-4000-8000-000000001201';
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF (platform.ensure_contact('40000000-0000-4000-8000-000000001202','synthetic-person-1@example.invalid','synthetic','Test Contact')='50000000-0000-4000-8000-000000010101'::uuid) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF;IF (NOT EXISTS(SELECT 1 FROM platform.contacts WHERE id='50000000-0000-4000-8000-000000010001')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|same_identity_in_business_B_stays_separate'; END $test$;
SET LOCAL app.business_id='40000000-0000-4000-8000-000000001101';
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN INSERT INTO platform.contacts(business_id,display_name,status) VALUES('40000000-0000-4000-8000-000000001101','Test','active'); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|direct_contact_insert_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN UPDATE platform.contacts SET display_name='Forged'; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|direct_contact_update_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN DELETE FROM platform.contacts; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|direct_contact_delete_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN UPDATE platform.channel_identities SET contact_id='50000000-0000-4000-8000-000000010101'; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|direct_identity_rebinding_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN EXECUTE 'SET ROLE pos_owner'; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|runtime_cannot_assume_owner'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF (NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace WHERE ns.nspname IN ('platform','crm') AND (NOT p.prosecdef OR p.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog']::text[] OR EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) ac WHERE ac.grantee=0 AND ac.privilege_type='EXECUTE')))) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|functions_have_fixed_path_and_no_public_execute'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN IF ((SELECT count(*)=2 FROM crm.leads)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF;IF ((SELECT stage='qualified' AND version=3 FROM crm.leads WHERE contact_id='50000000-0000-4000-8000-000000010001')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|two_seed_leads_visible_and_progressed_stage_preserved'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM crm.apply_lead_event('50000000-0000-4000-8000-000000010101','cross','new',0); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|cross_tenant_lead_command_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN PERFORM crm.apply_lead_event('50000000-0000-4000-8000-000000010003','blocked','new',0); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|blocked_contact_cannot_create_lead'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN c:=platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-new@example.invalid','synthetic','Test Contact'); r:=crm.apply_lead_event(c,'p5-new','new',0); IF (r->>'version'='1' AND r->>'replayed'='false') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; PERFORM crm.apply_lead_event(c,'p5-contacted','contacted',1); PERFORM crm.apply_lead_event(c,'p5-qualified','qualified',2); r:=crm.apply_lead_event(c,'p5-new','new',0); IF (r->>'version'='1' AND r->>'stage'='new' AND r->>'replayed'='true') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT stage='qualified' AND version=3 FROM crm.leads WHERE contact_id=c)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT count(*)=3 FROM crm.lead_events WHERE lead_id=(r->>'lead_id')::uuid)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT count(*)=3 FROM platform.audit_events WHERE event_type='crm.lead_transition' AND resource_ref=r->>'lead_id')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|lead_create_advance_replay_returns_original_outcome'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN c:=platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-new@example.invalid','synthetic','Test Contact'); BEGIN PERFORM crm.apply_lead_event(c,'p5-new','lost',0); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '22023' THEN NULL; END; RAISE NOTICE 'P5PASS|same_event_key_changed_payload_rejected'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN c:=platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-new@example.invalid','synthetic','Test Contact'); BEGIN PERFORM crm.apply_lead_event(c,'p5-stale','won',2); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '40001' THEN NULL; END; RAISE NOTICE 'P5PASS|stale_expected_version_rejected'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN c:=platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-new@example.invalid','synthetic','Test Contact'); BEGIN PERFORM crm.apply_lead_event(c,'p5-reset','new',3); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '22023' THEN NULL; END; RAISE NOTICE 'P5PASS|general_inquiry_cannot_reset_progressed_lead'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN c:=platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-new@example.invalid','synthetic','Test Contact'); PERFORM set_config('app.actor_ref','changed_actor',true); BEGIN PERFORM crm.apply_lead_event(c,'p5-new','new',0); RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '22023' THEN NULL; END; PERFORM set_config('app.actor_ref','phase5_test_actor',true); RAISE NOTICE 'P5PASS|changed_actor_cannot_replay_event'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN c:=platform.ensure_contact('40000000-0000-4000-8000-000000001102','phase5-rollback@example.invalid','synthetic','Test Contact'); SELECT count(*) INTO n FROM platform.audit_events; BEGIN PERFORM crm.apply_lead_event(c,'p5-rollback','new',0); PERFORM 1/0; EXCEPTION WHEN division_by_zero THEN NULL; END; IF (NOT EXISTS(SELECT 1 FROM crm.leads WHERE contact_id=c)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF (NOT EXISTS(SELECT 1 FROM crm.lead_events WHERE source_event_key='p5-rollback')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; IF ((SELECT count(*)=n FROM platform.audit_events)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Assertion failed'; END IF; RAISE NOTICE 'P5PASS|failed_outer_operation_rolls_back_lead_event_and_audit'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN UPDATE crm.leads SET stage='new'; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|raw_lead_update_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN UPDATE crm.lead_events SET to_stage='won'; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|event_update_denied'; END $test$;
DO $test$ DECLARE c uuid; r jsonb; n bigint; BEGIN BEGIN DELETE FROM crm.lead_events; RAISE EXCEPTION 'Expected rejection'; EXCEPTION WHEN SQLSTATE '42501' THEN NULL; END; RAISE NOTICE 'P5PASS|event_delete_denied'; END $test$;
ROLLBACK;
